#define BRRED            0XFC07 //棕红色
#define GRAY             0X8430 //灰色

typedef struct lcd_buffer_t {
    unsigned int size;
    unsigned int phys_addr;
    unsigned long   base;
    unsigned long   virt_addr;
} lcd_buffer_t;




typedef struct
{
    unsigned char cmd;
    unsigned char data[16];
    unsigned char databytes; //The number of data in data[]; bit 7 = delay flag after set; 0xFF = end of cmds.
    int delay_ms;
} lcd_init_cmd_t;
/*
 * Ioctl definitions
 */
